-- Test fixture, not product evidence. A hand-written imitation of how DDL
-- extraction tools commonly regenerate examples/varied-schema.sql: delimited
-- names, explicit defaults, every PBR partition listed, keys added by ALTER
-- TABLE after their indexes, DATA CAPTURE set by ALTER TABLE, generated
-- constraint names, FOR subtype DATA, and INCLUSIVE partition boundaries.
-- Every object keeps the exemplar's semantics, so `tools/ddl.py diff` must
-- report no `different` or `missing` entry.
-- tests/test_db2check.py seeds single-attribute defects into this file and
-- requires the diff to report each one.

SET CURRENT SQLID = 'QAV';

  CREATE DATABASE QAVDB01
    BUFFERPOOL BP0
    INDEXBP BP0
    STOGROUP SYSDEFLT
    CCSID EBCDIC
  ;

  CREATE TABLESPACE QAVS01
    IN QAVDB01
    USING STOGROUP SYSDEFLT
      PRIQTY -1
      SECQTY -1
      ERASE NO
    FREEPAGE 10
    PCTFREE 15 FOR UPDATE 10
    GBPCACHE CHANGED
    TRACKMOD NO
    MAXPARTITIONS 8
    LOGGED
    DSSIZE 1 G
    SEGSIZE 32
    BUFFERPOOL BP0
    LOCKSIZE ROW
    LOCKMAX 1000
    CLOSE NO
    COMPRESS YES
    CCSID EBCDIC
    DEFINE YES
    MAXROWS 100
    INSERT ALGORITHM 0
  ;

  CREATE TABLESPACE QAVS02
    IN QAVDB01
    USING STOGROUP SYSDEFLT
      PRIQTY -1
      SECQTY -1
      ERASE NO
    FREEPAGE 0
    PCTFREE 5
    GBPCACHE CHANGED
    TRACKMOD YES
    MAXPARTITIONS 2
    LOGGED
    DSSIZE 4 G
    SEGSIZE 4
    BUFFERPOOL BP0
    LOCKSIZE PAGE
    LOCKMAX 0
    CLOSE YES
    COMPRESS NO
    CCSID UNICODE
    DEFINE YES
    MAXROWS 255
    MEMBER CLUSTER
  ;

  CREATE TABLESPACE QAVS03
    IN QAVDB01
    NUMPARTS 3
    (PARTITION 1
       USING STOGROUP SYSDEFLT PRIQTY -1 SECQTY -1 ERASE NO
       FREEPAGE 5 PCTFREE 20 GBPCACHE CHANGED COMPRESS NO TRACKMOD YES
    ,PARTITION 2
       USING STOGROUP SYSDEFLT PRIQTY -1 SECQTY -1 ERASE NO
       FREEPAGE 0 PCTFREE 5 GBPCACHE CHANGED COMPRESS NO TRACKMOD YES
    ,PARTITION 3
       USING STOGROUP SYSDEFLT PRIQTY -1 SECQTY -1 ERASE NO
       FREEPAGE 0 PCTFREE 5 GBPCACHE CHANGED COMPRESS YES TRACKMOD YES
    )
    PAGENUM RELATIVE
    LOGGED
    DSSIZE 4 G
    SEGSIZE 64
    BUFFERPOOL BP0
    LOCKSIZE ANY
    LOCKMAX SYSTEM
    CLOSE YES
    CCSID EBCDIC
    DEFINE YES
    MAXROWS 255
  ;

  CREATE TABLESPACE QAVS04
    IN QAVDB01
    USING STOGROUP SYSDEFLT
      PRIQTY -1
      SECQTY -1
      ERASE NO
    FREEPAGE 0
    PCTFREE 5
    GBPCACHE CHANGED
    TRACKMOD YES
    MAXPARTITIONS 254
    LOGGED
    DSSIZE 4 G
    SEGSIZE 32
    BUFFERPOOL BP0
    LOCKSIZE ROW
    LOCKMAX SYSTEM
    CLOSE YES
    COMPRESS NO
    CCSID EBCDIC
    DEFINE YES
    MAXROWS 255
  ;

  CREATE TABLE "QAV"."CUSTOMER"
    ("CUSTOMER_ID" INTEGER NOT NULL
       GENERATED ALWAYS AS IDENTITY
       (START WITH 1000, INCREMENT BY 1, MINVALUE 1000,
        MAXVALUE 2147483647, NO CYCLE, CACHE 50, NO ORDER)
    ,"CUSTOMER_CODE" CHAR(10) FOR SBCS DATA NOT NULL
    ,"DISPLAY_NAME" VARCHAR(120) FOR SBCS DATA NOT NULL
    ,"STATUS" CHAR(1) FOR SBCS DATA NOT NULL WITH DEFAULT 'A'
    ,"CREDIT_LIMIT" DECIMAL(15, 2) NOT NULL WITH DEFAULT
    ,"RISK_SCORE" FLOAT(21)
    ,"TAX_REF" VARCHAR(32) FOR SBCS DATA
    ,"CREATED_BY" VARCHAR(128) FOR SBCS DATA NOT NULL WITH DEFAULT USER
    ,"CHANGED_TS" TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL
       GENERATED ALWAYS FOR EACH ROW ON UPDATE AS ROW CHANGE TIMESTAMP
    ,"AUDIT_NOTE" VARCHAR(200) FOR SBCS DATA IMPLICITLY HIDDEN
    ,CONSTRAINT "CUSTOMER_CK" CHECK ("STATUS" IN ('A', 'I', 'S'))
    )
    IN QAVDB01.QAVS01
    AUDIT ALL
    CCSID EBCDIC
    NOT VOLATILE
    APPEND NO
  ;

  CREATE TABLE "QAV"."PRODUCT"
    ("PRODUCT_ID" BIGINT NOT NULL
       GENERATED BY DEFAULT AS IDENTITY
       (START WITH 1, INCREMENT BY 1, MINVALUE 1,
        MAXVALUE 9223372036854775807, NO CYCLE, CACHE 20, NO ORDER)
    ,"SKU" VARCHAR(40) FOR MIXED DATA NOT NULL
    ,"LOCAL_NAME" VARGRAPHIC(60) NOT NULL
    ,"SHORT_CODE" GRAPHIC(4)
    ,"BARCODE" BINARY(16)
    ,"THUMB_HASH" VARBINARY(64)
    ,"LIST_PRICE" DECFLOAT(34)
    ,"WEIGHT_KG" DOUBLE
    ,"RELEASED" DATE
    ,"OWNER_ID" VARCHAR(128) FOR MIXED DATA WITH DEFAULT CURRENT SQLID
    ,"NOTE" VARCHAR(100) FOR MIXED DATA WITH DEFAULT NULL
    ,CONSTRAINT "PRODUCT_PK" PRIMARY KEY ("PRODUCT_ID")
    ,CONSTRAINT "PRODUCT_SKU_UK" UNIQUE ("SKU")
    )
    IN QAVDB01.QAVS02
    AUDIT CHANGES
    DATA CAPTURE NONE
    CCSID UNICODE
    VOLATILE CARDINALITY
    APPEND YES
  ;

  CREATE TABLE "QAV"."SALES_ORDER"
    ("ORDER_ID" BIGINT NOT NULL
    ,"ORDER_DATE" DATE NOT NULL
    ,"CUSTOMER_ID" INTEGER NOT NULL
    ,"CUSTOMER_CODE" CHAR(10) FOR SBCS DATA
    ,"CHANNEL" CHAR(3) FOR SBCS DATA NOT NULL WITH DEFAULT 'WEB'
    ,"ORDER_TOTAL" DECIMAL(17, 2) NOT NULL
    ,"PLACED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL
    ,"PICK_TIME" TIME
    ,CONSTRAINT "ORDER_TOTAL_CK" CHECK ("ORDER_TOTAL" >= 0)
    )
    IN QAVDB01.QAVS03
    PARTITION BY RANGE ("ORDER_DATE" ASC)
    (PARTITION 1 ENDING AT ('2024-12-31') INCLUSIVE
    ,PARTITION 2 ENDING AT ('2025-12-31') INCLUSIVE
    ,PARTITION 3 ENDING AT (MAXVALUE) INCLUSIVE
    )
    AUDIT NONE
    DATA CAPTURE NONE
    CCSID EBCDIC
    NOT VOLATILE
    APPEND NO
  ;

  CREATE TABLE "QAV"."ORDER_LINE"
    ("ORDER_ID" BIGINT NOT NULL
    ,"LINE_NO" SMALLINT NOT NULL
    ,"PRODUCT_ID" BIGINT NOT NULL
    ,"QTY" INTEGER NOT NULL
    ,"PARENT_ORDER_ID" BIGINT
    ,"PARENT_LINE_NO" SMALLINT
    ,CONSTRAINT "LINE_QTY_CK" CHECK ("QTY" > 0)
    )
    IN QAVDB01.QAVS04
    AUDIT NONE
    DATA CAPTURE NONE
    CCSID EBCDIC
  ;

  CREATE UNIQUE INDEX "QAV"."CUSTOMER_PKIX"
    ON "QAV"."CUSTOMER"
    ("CUSTOMER_ID" ASC)
    USING STOGROUP SYSDEFLT PRIQTY -1 SECQTY -1 ERASE NO
    FREEPAGE 0
    PCTFREE 10
    GBPCACHE CHANGED
    CLUSTER
    COMPRESS NO
    INCLUDE NULL KEYS
    BUFFERPOOL BP0
    CLOSE YES
    COPY NO
    DEFER NO
    DEFINE YES
  ;

  CREATE UNIQUE INDEX "QAV"."CUSTOMER_UKIX"
    ON "QAV"."CUSTOMER"
    ("CUSTOMER_CODE" ASC)
    INCLUDE ("STATUS")
    USING STOGROUP SYSDEFLT PRIQTY -1 SECQTY -1 ERASE NO
    NOT CLUSTER
    BUFFERPOOL BP0
    CLOSE YES
  ;

  CREATE UNIQUE WHERE NOT NULL INDEX "QAV"."CUSTOMER_TAXIX"
    ON "QAV"."CUSTOMER"
    ("TAX_REF" ASC)
    NOT CLUSTER
    NOT PADDED
    BUFFERPOOL BP0
  ;

  CREATE UNIQUE INDEX "QAV"."PRODUCT_PKIX"
    ON "QAV"."PRODUCT"
    ("PRODUCT_ID" ASC)
    NOT CLUSTER
    BUFFERPOOL BP0
  ;

  CREATE UNIQUE INDEX "QAV"."PRODUCT_SKUIX"
    ON "QAV"."PRODUCT"
    ("SKU" DESC)
    NOT CLUSTER
    PADDED
    FREEPAGE 31
    PCTFREE 0
    BUFFERPOOL BP0
  ;

  CREATE UNIQUE INDEX "QAV"."ORDER_PKIX"
    ON "QAV"."SALES_ORDER"
    ("ORDER_ID" ASC)
    NOT CLUSTER
    BUFFERPOOL BP0
  ;

  CREATE INDEX "QAV"."ORDER_DATEIX"
    ON "QAV"."SALES_ORDER"
    ("ORDER_DATE" ASC, "CUSTOMER_ID" ASC)
    CLUSTER
    PARTITIONED
    PARTITION BY RANGE
    (PARTITION 1 USING STOGROUP SYSDEFLT PRIQTY -1 SECQTY -1 ERASE NO
       FREEPAGE 0 PCTFREE 10 GBPCACHE CHANGED
    ,PARTITION 2 USING STOGROUP SYSDEFLT PRIQTY -1 SECQTY -1 ERASE NO
       FREEPAGE 0 PCTFREE 10 GBPCACHE CHANGED
    ,PARTITION 3 USING STOGROUP SYSDEFLT PRIQTY -1 SECQTY -1 ERASE NO
       FREEPAGE 0 PCTFREE 10 GBPCACHE CHANGED
    )
    BUFFERPOOL BP0
  ;

  CREATE INDEX "QAV"."ORDER_CUSTIX"
    ON "QAV"."SALES_ORDER"
    ("CUSTOMER_ID" DESC)
    NOT CLUSTER
    BUFFERPOOL BP0
  ;

  CREATE UNIQUE INDEX "QAV"."LINE_PKIX"
    ON "QAV"."ORDER_LINE"
    ("ORDER_ID" ASC, "LINE_NO" ASC)
    NOT CLUSTER
    BUFFERPOOL BP0
  ;

  ALTER TABLE "QAV"."CUSTOMER"
    ADD CONSTRAINT "CUSTOMER_PK" PRIMARY KEY ("CUSTOMER_ID")
  ;

  ALTER TABLE "QAV"."CUSTOMER"
    ADD CONSTRAINT "CUSTOMER_UK" UNIQUE ("CUSTOMER_CODE")
  ;

  ALTER TABLE "QAV"."CUSTOMER"
    DATA CAPTURE CHANGES
  ;

  ALTER TABLE "QAV"."SALES_ORDER"
    ADD CONSTRAINT "ORDER_PK" PRIMARY KEY ("ORDER_ID")
  ;

  ALTER TABLE "QAV"."ORDER_LINE"
    ADD CONSTRAINT "LINE_PK" PRIMARY KEY ("ORDER_ID", "LINE_NO")
  ;

  ALTER TABLE "QAV"."SALES_ORDER"
    ADD CONSTRAINT "ORDER_CUSTOMER_FK" FOREIGN KEY ("CUSTOMER_ID")
    REFERENCES "QAV"."CUSTOMER" ("CUSTOMER_ID")
    ON DELETE RESTRICT ENFORCED
  ;

  ALTER TABLE "QAV"."SALES_ORDER"
    ADD CONSTRAINT "ORDER_CODE_FK" FOREIGN KEY ("CUSTOMER_CODE")
    REFERENCES "QAV"."CUSTOMER" ("CUSTOMER_CODE")
    ON DELETE SET NULL ENFORCED
  ;

  ALTER TABLE "QAV"."ORDER_LINE"
    ADD CONSTRAINT "PRODUCT_ID" FOREIGN KEY ("PRODUCT_ID")
    REFERENCES "QAV"."PRODUCT" ("PRODUCT_ID")
    ON DELETE CASCADE ENFORCED
  ;

  ALTER TABLE "QAV"."ORDER_LINE"
    ADD CONSTRAINT "LINE_ORDER_FK" FOREIGN KEY ("ORDER_ID")
    REFERENCES "QAV"."SALES_ORDER" ("ORDER_ID")
    NOT ENFORCED ENABLE QUERY OPTIMIZATION
  ;

  ALTER TABLE "QAV"."ORDER_LINE"
    ADD CONSTRAINT "LINE_PARENT_FK" FOREIGN KEY ("PARENT_ORDER_ID", "PARENT_LINE_NO")
    REFERENCES "QAV"."ORDER_LINE" ("ORDER_ID", "LINE_NO")
    ON DELETE NO ACTION ENFORCED
  ;

  CREATE TABLE "QAV"."PRODUCT_DOC"
    ("DOC_ID" INTEGER NOT NULL
    ,"PRODUCT_ID" BIGINT NOT NULL
    ,"BODY" CLOB(1048576) FOR SBCS DATA
    ,CONSTRAINT "DOC_PK" PRIMARY KEY ("DOC_ID")
    ,CONSTRAINT "DOC_PRODUCT_FK" FOREIGN KEY ("PRODUCT_ID")
       REFERENCES "QAV"."PRODUCT" ("PRODUCT_ID") ON DELETE RESTRICT ENFORCED
    )
    IN DATABASE QAVDB01
    CCSID EBCDIC
  ;

  COMMENT ON TABLE "QAV"."CUSTOMER" IS 'Customer master';
  LABEL ON TABLE "QAV"."CUSTOMER" IS 'Customers';
  GRANT SELECT ON TABLE "QAV"."CUSTOMER" TO PUBLIC;
  COMMIT;
